/**
 * Tạo phần tử SVG span với icon
 * @param {string} name - Tên icon trong Icons
 * @param {string} [className] - Class CSS tùy chọn
 * @returns {string} HTML string
 */
export function iconHtml(name, className = '') {
  const svg = Icons[name];
  if (!svg) return '';
  return className
    ? svg.replace('<svg ', `<svg class="${className}" `)
    : svg;
}
